(N'7226dafb-9f1b-53e3-b00c-934454ea0639',N'22b8b4f5-9771-5c73-a5a1-87b9a458c287',0,3,19,N'Question number 13',N'<p>- Đáp án là C - “get your provisional driving license” → bằng tạm.</p><p>- Key word: </p><p>+ provisional (adj): tạm thời </p><p>+ license (n): bằng lái</p>',NULL,NULL,NULL,0,0,13,NULL,0,1982),
(N'ca1b0ca1-1053-5f42-9286-c9c56c8ca9ea',N'22b8b4f5-9771-5c73-a5a1-87b9a458c287',0,3,19,N'Question number 14',N'<p>- Đáp án là B - “on our specially designed circuit” → circuit-based.</p><p>- Key word: </p><p>+ circuit (n): đường vòng </p><p>+ assessment (n): đánh giá</p>',NULL,NULL,NULL,0,0,14,NULL,0,1982),
(N'40b38ed9-5e5d-5d46-8717-3f214d600ffe',N'22b8b4f5-9771-5c73-a5a1-87b9a458c287',0,3,19,N'Question number 15',N'<p>- Đáp án là H - “official test run by the RTD” → RTD test.</p><p>- Key word: </p><p>+ official test (n): bài thi chính thức</p><p> + RTD (n): cơ quan giao thông</p>',NULL,NULL,NULL,0,0,15,NULL,0,1982),
(N'16f8df7b-eb2f-579d-8aa3-fe23301ad100',N'22b8b4f5-9771-5c73-a5a1-87b9a458c287',0,3,19,N'Question number 16',N'<p>Đáp án là A - “on probation for a year” → 12 months probation.</p><p>- Key word: </p><p>+ probation (n): thử thách </p><p>+ year (n): năm</p>',NULL,NULL,NULL,0,0,16,NULL,0,1982),
