(N'a2e9c84d-9f58-5c59-aa82-2bbf2667165b',N'3ce356df-56b8-538b-a17b-5a4d8067c502',0,3,19,N'<p>Performing solo</p>',N'<p>Đáp án là B - “challenging… stimulating” → khó nhưng thú vị.</p><p>- Key word: </p><p>+ challenging (adj): thử thách </p><p>+ stimulating (adj): thú vị</p>',NULL,NULL,NULL,0,0,27,NULL,0,1982),
