(N'fa6f65fe-d934-5373-aa3a-f6d4b507e292',N'fa8ebbc0-b71d-522d-a79f-97d2fdbe36cd',0,3,19,N'Question number 6',N'<p>Đáp án là office - “purchased in the office” → mua gỗ tại văn phòng.</p><p>- Key word: </p><p>+ purchased (v): mua </p><p>+ office (n): văn phòng</p>',NULL,NULL,NULL,0,0,6,NULL,0,1980),
