(N'6bbb58c4-2570-51ae-a32c-9ca65b2be372',N'0ce370d9-ddb6-5cea-8cc6-7b231970b2d1',0,3,19,N'<p>Last year''s winning film was about</p>',N'<p>- Đáp án là C </p><p>- “cycle to school instead of car” → phương tiện giao thông xanh. </p><p>- A, B không được nhắc. </p><p>- Key word: </p><p>+ cycle (v): đi xe đạp </p><p>+ environmental issues (n): vấn đề môi trường</p>',NULL,NULL,NULL,0,0,14,NULL,0,1980),
