(N'549f8d69-af88-5f73-86d8-8ae0b37f7dca',N'7c4854f3-4ce5-5a2c-b4ff-6062f8e3f633',0,3,19,N'Question number 38',N'<p>- Đáp án là cotton </p><p>- “sponges made from cotton” → bọt biển từ cotton.</p><p>- Key word:</p><p>+ cotton (n): bông</p><p>+ sponge (n): miếng bọt</p>',NULL,NULL,NULL,0,0,38,NULL,0,1980),
