(N'25f5794c-ad91-521e-9ee0-835e86a419e8',N'7c4854f3-4ce5-5a2c-b4ff-6062f8e3f633',0,3,19,N'Question number 40',N'<p>- Đáp án là saliva </p><p>- Script: “human saliva” → nước bọt.</p><p>- Key word:</p><p>+ saliva (n): nước bọt</p><p>+ liquid (n): chất lỏng</p>',NULL,NULL,NULL,0,0,40,NULL,0,1980),
