(N'e1be1785-8e71-5403-a56b-382650c15602',N'5e772504-ca09-53d3-8a6c-6be9a66f541f',0,3,19,N'Question number 36',N'<p>- Đáp án là 200 years old - “reach 200” → tuổi tối đa 200 năm</p><p>- Key word:</p><p>+ reach (v): đạt tới</p><p>+ years (n): năm</p>',NULL,NULL,NULL,0,0,36,NULL,0,1977),
(N'ec5e76f1-208a-5984-b512-950d718594ab',N'5e772504-ca09-53d3-8a6c-6be9a66f541f',0,3,19,N'Question number 37',N'<p>- Đáp án là 0.1 of a centimetre - “0.1 of a centimetre a year” → tốc độ tăng trưởng</p><p>- Key word:</p><p>+ centimetre (n): cm</p><p>+ grow (v): phát triển</p>',NULL,NULL,NULL,0,0,37,NULL,0,1977),
