(N'5374be69-1c00-54f4-8280-740936aec794',N'6ac6f395-467b-5175-8ea4-bbce5b22c7c5',0,3,19,N'Question number 32',N'<p>- Đáp án là soil </p><p>- “consumes soil” → ăn đất để lấy khoáng chất </p><p>- Khớp với câu hỏi về minerals</p><p>- Key word: </p><p>+ soil (n): đất </p><p>+ minerals (n): khoáng chất</p>',NULL,NULL,NULL,0,0,32,NULL,0,1888),
