(N'e9dada4f-9798-5eba-a86c-951dccf7080f',N'8a38aa81-4d9c-55a5-b359-cc43f092c80d',0,3,19,N'<h3>Advice to Visitors</h3><p>Bring your own }{SPACE}{ and insect spray.</p><p>It may not be possible to use your }{SPACE}{ in the western area.</p><p>Don''t drink water from }{SPACE}{ </p><p>Be careful of the  }{SPACE}{  as they bite.</p><p>Try the local }{SPACE}{ </p>',N'<p>Hỏi: Bring your own ___ and insect spray. </p><p>→ Nghe thấy rõ “medication”. </p><p>→ Đáp án: medication.</p>',NULL,NULL,NULL,0,0,16,NULL,0,1673),
