(N'5f1f79f3-b745-5b27-90c1-b7284697191e',N'e2c4e2dd-b1c8-5c3a-98eb-6ac4368113cb',0,3,19,N'<p>Edward heard about a type of mosquito net from</p>',N'<p>Edward nói chuyện với administrator (quản lý) trong trung tâm y tế và từ đó biết về hiệu quả của màn chống muỗi. </p><p>→ Đáp án A. an administrator. Hai đáp án còn lại (doctor, friend) đều xuất hiện trong bối cảnh khác, dễ gây nhiễu.</p>',NULL,NULL,NULL,0,0,21,NULL,0,1670),
(N'8a542f7e-2c9b-5701-91bc-e4627f2186a1',N'e2c4e2dd-b1c8-5c3a-98eb-6ac4368113cb',0,3,19,N'<p>Edward believes that mosquito nets were first used in</p>',N'<p>Từ khóa “invented” và “Egypt” cho thấy màn chống muỗi xuất hiện đầu tiên ở Ai Cập cổ đại. </p><p>→ C. Egypt</p>',NULL,NULL,NULL,0,0,22,NULL,0,1670),
(N'51a6bcba-0569-54bf-8b51-aec1ce4dfd1b',N'e2c4e2dd-b1c8-5c3a-98eb-6ac4368113cb',0,3,19,N'<p>Chemical treatment of mosquito nets in the mid-twentieth century</p>',N'<p>Việc xử lý màn bằng hóa chất khiến chúng “nguy hiểm cho người dùng”. </p><p>→ B. made them potentially dangerous to users.</p>',NULL,NULL,NULL,0,0,23,NULL,0,1670),
(N'1f6cb057-6edb-5830-ae61-01322679547a',N'e2c4e2dd-b1c8-5c3a-98eb-6ac4368113cb',0,3,19,N'<p>The owners of present-day nets</p>',N'<p>Người dân vùng xa “khó tiếp cận hóa chất cần thiết” để tái xử lý màn. </p><p>→ C. may have difficulty obtaining the necessary chemical.</p>',NULL,NULL,NULL,0,0,24,NULL,0,1670),
(N'0661b350-597f-517f-9f15-9363e403808a',N'e2c4e2dd-b1c8-5c3a-98eb-6ac4368113cb',0,3,19,N'<p>According to Edward, Olyset nets are better than other nets because they</p>',N'<p>Olyset có hiệu quả lâu hơn. </p><p>→ A. remain effective for longer. Các đáp án “more chemicals” và “protect more insects” sai với nội dung.</p>',NULL,NULL,NULL,0,0,25,NULL,0,1670),
