(N'032abb8e-c0b6-5b90-9e29-a6f8039d9994',N'a37ffc43-c1c9-578e-b9ac-3e62ce0fe308',0,3,19,N'<p><span>Context: need for anti-malarial products</span></p><p>Figures relating to:</p><ul><li><p>global incidence of the disease</p></li></ul><ul><li><p>impact on</p></li></ul> }{SPACE}{ </p><p><span>Mosquito nets</span></p><ul><li><p>history</p></li></ul><ul><li><p></p></li></ul> }{SPACE}{ </p><p><span>Production</span></p><ul><li><p>information about</p></li></ul> }{SPACE}{ </p><ul><li><p>profile of manufacturer with description of</p></li></ul> }{SPACE}{ </p><ul><li><p></p></li></ul> }{SPACE}{ (according to website)</p>',N'<p>“Economic output” = kinh tế quốc gia → G. national economies.</p>',NULL,NULL,NULL,0,0,26,NULL,0,1670),
