(N'9b324ef9-e4c6-5f36-b225-c661c440ab2e',N'5f2ad6b1-d300-5c9d-a93b-2f522dde8bd7',0,3,19,N'Question number 35',N'<p>Câu hỏi: “Stone stands and ___.” </p><p>→ stone stands and coins </p><p>→ có đồng xu bạc dùng làm tiền.</p>',NULL,NULL,NULL,0,0,35,NULL,0,1668),
