(N'fb921622-28f9-58e9-b2e7-e764157963ff',N'47ae420a-fdec-5732-a402-02cd5ac7a07a',0,3,19,N'Question number 35',N'<p>- Đáp án là therapy. </p><p>- Câu đầu khẳng định vai trò của đóng vai như một hình thức trị liệu cho trẻ gặp khó khăn. </p><p>- Câu sau giải thích cách nó giúp trẻ nhìn nhận hành vi khách quan hơn. </p><p>- Key words: therapy: trị liệu </p>',NULL,NULL,NULL,0,0,35,NULL,0,1664),
(N'd4be85cf-816b-5d6e-a63b-319a19239140',N'47ae420a-fdec-5732-a402-02cd5ac7a07a',0,3,19,N'Question number 36',N'<p>- Đáp án là safe. </p><p>- Giáo viên có thể khai thác chủ đề nhạy cảm trong môi trường an toàn. </p><p>- Trẻ cảm thấy không bị phán xét nên dám bày tỏ ý kiến. </p><p>- Key words: safe setting: môi trường an toàn </p>',NULL,NULL,NULL,0,0,36,NULL,0,1664),
(N'0a9e3ae5-d2eb-5f19-bd1d-d8054695172e',N'47ae420a-fdec-5732-a402-02cd5ac7a07a',0,3,19,N'Question number 37',N'<p>- Đáp án là morality. </p><p>- Đoạn này nói rõ vai trò của kịch trong việc giúp trẻ hiểu rõ hơn về đạo đức. </p><p>- Key words: morality: đạo đức </p>',NULL,NULL,NULL,0,0,37,NULL,0,1664),
