(N'8a81d66f-550c-593f-8d85-ea29734de19a',N'2fbdefd4-e1a9-5783-83ac-3a9f53e9c6aa',0,3,19,N'<p>What do the speakers agree are the <span>TWO</span> reasons why children play outdoors less
now than in the past?</p>',N'<p>Đáp án là E. Ravi giải thích rằng trẻ em hiện nay có ít thời gian rảnh hơn do tham gia nhiều hoạt động có tổ chức, làm giảm thời gian dành cho chơi ngoài trời. Key words: structured activities, out-of-school clubs, less time.</p>',NULL,NULL,NULL,0,0,22,NULL,0,1662),
(N'ea933f1f-27f6-5cdf-9ec3-18c5430c67b3',N'a3c2a920-68c8-5429-8612-304150879132',0,2,18,N'<p>Choose<span> TWO</span> letters,<span> A-E.</span></p>',N'',N'',N'',N'',5,0,2,NULL,0,1662),
(N'237c95e2-b54f-57b9-a939-b2da805d49fb',N'ea933f1f-27f6-5cdf-9ec3-18c5430c67b3',0,3,19,N'<p>In his assignment, which <span>TWO</span> aspects of outdoor play does Ravi want to focus on?</p>',N'<p>Đáp án là A. Ravi muốn tập trung vào việc chơi ngoài trời giúp trẻ học cách đánh giá rủi ro và đưa ra quyết định, được nhắc trực tiếp trong hội thoại. Key words: decisions, dangerous, evaluate risk.

</p>',NULL,NULL,NULL,0,0,23,NULL,0,1662),
(N'baa63779-1356-5eda-9308-a98404ba4756',N'ea933f1f-27f6-5cdf-9ec3-18c5430c67b3',0,3,19,N'<p>In his assignment, which <span>TWO</span> aspects of outdoor play does Ravi want to focus on?</p>',N'<p>Đáp án là D. Ravi nói rõ anh muốn nghiên cứu tác động của chơi ngoài trời đến tiêu hóa của trẻ, do không khí trong lành kích thích cảm giác đói. Key words: digestion, fresh air, hunger.</p>',NULL,NULL,NULL,0,0,24,NULL,0,1662),
