(N'bddc0ebe-b03f-5dac-ba4b-13cefb12f3cb',N'33d8ceb4-3fd4-550b-8944-16cabd115946',0,3,19,N'<p><img src="https://ieltsroom.com/upload/images/ieltsadvancedtest/39881c02fc43ac2d1481.png" alt="Question diagram"></p> }{SPACE}{  }{SPACE}{  }{SPACE}{ ',N'<p>- Đáp án là Hill Park.  </p><p>- Người nói giới thiệu điểm dừng đầu tiên ngay sau khi rời văn phòng là Hill Park.  </p><p>- Đây là tên riêng nên phải viết đúng chính tả.</p>',NULL,NULL,NULL,0,0,13,NULL,0,1651),
(N'74c8401a-e0ce-5dde-8a15-72db93426c40',N'33d8ceb4-3fd4-550b-8944-16cabd115946',0,3,19,N'Question number 14',N'<p>- Đáp án là Bay Bridge.  </p><p>- Người nói nói rõ đây là điểm dừng thứ ba, nằm ở chân cầu bắc qua vịnh.  </p><p>- Từ khóa: third stop, Bay Bridge.</p>',NULL,NULL,NULL,0,0,14,NULL,0,1651),
(N'95aa7196-33c9-5aad-9782-da5a57b7385f',N'33d8ceb4-3fd4-550b-8944-16cabd115946',0,3,19,N'Question number 15',N'<p>- Đáp án là Green Street.  </p><p>- Đây là điểm dừng cuối cùng của tour.  </p><p>- Từ khóa quan trọng: fifth and last stop. </p>',NULL,NULL,NULL,0,0,15,NULL,0,1651),
