(N'2b0080dd-0822-5009-a02a-bbb04fcded44',N'fda8674c-616a-5770-aee4-da7c4127b8d0',0,3,19,N'<p>Puffing Billy</p>',N'<p>- Đáp án là D</p><p>- Puffing Billy ban đầu sử dụng động cơ dầu và sau đó được cải tiến dùng điện, tức là dùng hai nguồn năng lượng khác nhau</p><p>- Key word:+ oil engine: (noun) động cơ dầu+ powered: (adjective) chạy bằng năng lượng</p>',NULL,NULL,NULL,0,0,16,NULL,0,1642),
(N'66af3429-ba54-5011-bcdc-8858845a4b00',N'fda8674c-616a-5770-aee4-da7c4127b8d0',0,3,19,N'<p>Hoover</p>',N'<p>- Đáp án là F</p><p>- Hoover được đặt theo tên một người không phải là nhà phát minh ban đầu, mà là doanh nhân mua lại ý tưởng</p><p>- Key word:+ businessman: (noun) doanh nhân+ inventor: (noun) nhà phát minh</p>',NULL,NULL,NULL,0,0,17,NULL,0,1642),
(N'd0dbd43f-83f4-560d-a3ec-653af41d3c9c',N'fda8674c-616a-5770-aee4-da7c4127b8d0',0,3,19,N'<p>Electrolux Model V</p>',N'<p>- Đáp án là B</p><p>- Electrolux Model V được thiết kế nhẹ hơn và dễ di chuyển, đúng với mô tả “specially designed to be easy to move”</p><p>- Key word:+ lighter: (adjective) nhẹ hơn+ pull along: (verb phrase) kéo đi</p>',NULL,NULL,NULL,0,0,18,NULL,0,1642),
