(N'2ea51d22-3fc1-5c3a-a96a-2c9a5d85b7cd',N'7ff22c19-af54-5ebb-917c-f4ba46eca423',0,3,19,N'Question number 2',N'<p>Đáp án là main. Địa điểm tổ chức nhảy múa dân gian là tại hội trường chính của University Centre và cụm từ này được nhắc trực tiếp. Key words: meet: gặp, hall: hội trường. Scripts: in the main hall</p>',NULL,NULL,NULL,0,0,2,NULL,0,1586),
(N'1baad70d-8bc9-53bc-968c-56a8cab10ff8',N'7ff22c19-af54-5ebb-917c-f4ba46eca423',0,3,19,N'Question number 3',N'<p>Đáp án là partner. Khi được hỏi có cần mang theo bạn nhảy không, người nói khẳng định là không cần, ám chỉ không cần mang theo partner. Key words: need: cần, dancing: nhảy múa. Scripts: You don''t have to</p>',NULL,NULL,NULL,0,0,3,NULL,0,1586),
