(N'fd25b9d8-b02d-54d4-b46a-51912c5a6b13',N'7ff22c19-af54-5ebb-917c-f4ba46eca423',0,3,19,N'Question number 8',N'<p>Đáp án là charity. Cuộc đi bộ 15 km được tổ chức nhằm mục đích gây quỹ từ thiện. Key words: walk: đi bộ, for: cho. Scripts: for charity</p>',NULL,NULL,NULL,0,0,8,NULL,0,1586),
(N'47f85317-14d8-5ea1-b937-22a5cd3ca26d',N'7ff22c19-af54-5ebb-917c-f4ba46eca423',0,3,19,N'Question number 9',N'<p>Đáp án là swimming. Buổi tiệc vườn có hồ bơi ngoài trời và nếu thời tiết cho phép thì có thể bơi lội. Key words: outdoor pool: hồ bơi ngoài trời, weather: thời tiết. Scripts: go swimming</p>',NULL,NULL,NULL,0,0,9,NULL,0,1586),
