(N'6f7d9ca6-449a-5170-9a18-0ab062bd329d',N'51e0877a-8266-5657-a113-b2b758e4ff70',0,3,19,N'<p>Ken Simpson</p><p></p>',N'<p>Đáp án là A. Ken Simpson cho rằng để bảo vệ môi trường tự nhiên, chính phủ nên tắt đèn vào ban đêm, đây chính là việc áp đặt các hạn chế về chiếu sáng. Key words: turn off lights, protect natural habitats.</p>',NULL,NULL,NULL,0,0,21,NULL,0,1586),
(N'5bc56983-ff93-5fc0-8e6c-121cf390102c',N'51e0877a-8266-5657-a113-b2b758e4ff70',0,3,19,N'<p>Dave Kepler</p>',N'<p>Đáp án là B. Dave Kepler đề xuất thay thế hệ thống chiếu sáng hiện tại bằng các loại đèn thân thiện với môi trường hơn, tức là sử dụng nguồn chiếu sáng thay thế. Key words: replace lights, environmentally friendly, solar-powered.</p>',NULL,NULL,NULL,0,0,22,NULL,0,1586),
(N'14581437-ef52-513d-9560-4dc7fe03026d',N'51e0877a-8266-5657-a113-b2b758e4ff70',0,3,19,N'<p>Sharon Grey</p>',N'<p>Đáp án là F. Sharon Grey cho rằng ánh sáng ảnh hưởng đến số lượng côn trùng, từ đó tác động trực tiếp đến sự phát triển và kích thước của động vật ăn côn trùng. Key words: insect-eating animals, smaller in size, fewer insects.

</p>',NULL,NULL,NULL,0,0,23,NULL,0,1586),
(N'937b216a-8655-5f18-80fd-c88a2c8a3857',N'51e0877a-8266-5657-a113-b2b758e4ff70',0,3,19,N'<p>Maria Jackson</p>',N'<p>Đáp án là G. Maria Jackson cho rằng ánh sáng mặt trời ảnh hưởng đến đặc tính của nước, từ đó tác động đến chất lượng nước. Key words: sunlight, water quality.</p>',NULL,NULL,NULL,0,0,24,NULL,0,1586),
(N'7df34bc7-738e-5ad3-b33c-c13f38060315',N'51e0877a-8266-5657-a113-b2b758e4ff70',0,3,19,N'<p>Barbara Swallow</p>',N'<p>Đáp án là D. Barbara Swallow nghiên cứu sự suy giảm số lượng côn trùng và tác động tiêu cực của hiện tượng này tới các loài khác như ếch, phản ánh sự suy giảm số lượng loài. Key words: declined insect population, frog population.</p>',NULL,NULL,NULL,0,0,25,NULL,0,1586),
(N'b1138cf3-9913-592f-93fb-51494a991186',N'ea8b1299-73a1-516c-89ea-9c913b98141f',0,2,18,N'<p>Choose the correct letter, A, B or C.</p>',N'',N'',N'',N'',1,0,2,NULL,0,1586),
(N'c76dbc8c-3945-53df-98e4-b06d406546d0',N'b1138cf3-9913-592f-93fb-51494a991186',0,3,19,N'<p>What does Jim think about the difference among species in natural and artificial light?</p>',N'<p>Đáp án là B. Jim cho rằng dù sử dụng ánh sáng tự nhiên hay nhân tạo thì các loài vẫn sẽ chết dần, nên không có sự khác biệt đáng kể. Key words: no difference, die out either way.</p>',NULL,NULL,NULL,0,0,26,NULL,0,1586),
