(N'ce0cbc8c-a374-5389-86d4-0cdd7cf5cd2b',N'19c20c11-8792-5901-a529-6d5fb8c21344',0,3,19,N'Question number 32',N'<p>Đáp án là desert. Người nói khẳng định phần lớn diện tích Nam Cực được xếp vào loại sa mạc do lượng tuyết rơi rất thấp. Key words: low snowfall, category, desert</p>',NULL,NULL,NULL,0,0,32,NULL,0,1564),
(N'fab66697-2962-52f2-b40c-b1b0b4973a35',N'19c20c11-8792-5901-a529-6d5fb8c21344',0,3,19,N'Question number 33',N'<p>Đáp án là science. Câu nói trực tiếp nêu khoa học được tích hợp với hỗ trợ kỹ thuật tại các trạm nghiên cứu. Key words: science, technical support, integrated</p>',NULL,NULL,NULL,0,0,33,NULL,0,1564),
