(N'117b2d1d-d079-5141-a8be-17d4c857d903',N'19ee31cc-347a-5505-8660-51c8e4d37142',0,3,19,N'<h3>Family presents</h3><p><em><span>Company specialises in educational toys</span></em></p><p><span>Presents for Peter:</span></p><p>A wooden }{SPACE}{ (a model)</p><ul><li><p>includes a sheet of stickers</p></li></ul><ul><li><p>helps children to understand basic</p></li></ul> }{SPACE}{ </p><ul><li><p>price: £17.50</p></li></ul><p>A }{SPACE}{ feeder</p><ul><li><p>includes paints and brush</p></li></ul><ul><li><p>price: £</p></li></ul> }{SPACE}{ </p><p><span>Present for Natalie:</span></p><p>A chocolate pack</p><ul><li><p>kit includes chocolate, moulds and some small</p></li></ul> }{SPACE}{ </p><ul><li><p>develops artistic skills</p></li></ul><ul><li><p>helps children to understand effects of</p></li></ul> }{SPACE}{ </p><ul><li><p>price: £6.00</p></li></ul><p><span>Ordering toys</span></p><ul><li><p>web address – www.</p></li></ul> }{SPACE}{ .com</p><ul><li><p>order before Friday to get free</p></li></ul> }{SPACE}{ </p><ul><li><p>can be wrapped and sent straight to children</p></li></ul><ul><li><p>under ‘Packaging options’ choose</p></li></ul> }{SPACE}{ </p><ul><li><p>possible to include a</p></li></ul> }{SPACE}{ </p>',N'<p>Câu hỏi: “A wooden … (a model)” → Đáp án truck, vì trong script nhắc rõ “model truck made of wood”.</p>',NULL,NULL,NULL,0,0,1,NULL,0,1540),
(N'25bd8a06-da04-5113-a402-e7e923457516',N'19ee31cc-347a-5505-8660-51c8e4d37142',0,3,19,N'Question number 2',N'<p>Câu hỏi: “Helps children to understand basic …” → Đáp án technology, vì đây là kỹ năng mà đồ chơi hỗ trợ.</p>',NULL,NULL,NULL,0,0,2,NULL,0,1540),
(N'fd5afd82-a04c-5130-a61d-2f0e3c86b72d',N'19ee31cc-347a-5505-8660-51c8e4d37142',0,3,19,N'Question number 3',N'<p>Câu hỏi: “A 3 … feeder” → Đáp án bird, vì sản phẩm là bird feeder.</p>',NULL,NULL,NULL,0,0,3,NULL,0,1540),
