,NULL,0,0,31,NULL,0,1540),
(N'1a0721aa-d7b8-5d85-b01e-6c8ed04f34d0',N'348c809f-a49f-5048-be70-92ea858a209a',0,3,19,N'Question number 32',N'<p>Question: “Research into the intelligence of …” → Cần đối tượng nghiên cứu. Answer: twins. Key vocab: studies = research.</p>',NULL,NULL,NULL,0,0,32,NULL,0,1540),
(N'805704a9-ba8c-54b5-b8fa-cec1d526242c',N'348c809f-a49f-5048-be70-92ea858a209a',0,3,19,N'Question number 33',N'<p>Question: “Two children from the same family are likely to have similar … affecting their intelligence.” Answer: experiences. Key vocab: similar experiences.</p>',NULL,NULL,NULL,0,0,33,NULL,0,1540),
(N'8d18433f-5e60-5e1c-9f0e-436e104f2733',N'348c809f-a49f-5048-be70-92ea858a209a',0,3,19,N'Question number 34',N'<p>Question: “After moving to a different culture there was an … in children’s intelligence.” Answer: improvement. Key vocab: significant improvement.</p>',NULL,NULL,NULL,0,0,34,NULL,0,1540),
(N'd497c640-1dfd-51d8-9fef-f3b3e38f19f4',N'348c809f-a49f-5048-be70-92ea858a209a',0,3,19,N'Question number 35',N'<p>Question: “Non-traditional intelligence, e.g. …” Answer: musical. Key vocab: musical abilities = non-traditional.</p>',NULL,NULL,NULL,0,0,35,NULL,0,1540),
(N'9a8b2ffd-c7a1-5938-b494-2f89fb29c996',N'348c809f-a49f-5048-be70-92ea858a209a',0,3,19,N'Question number 36',N'<p>Question: “Research suggests different parts of the … control abilities.” Answer: brain. Key vocab: circuits in the brain.</p>',NULL,NULL,NULL,0,0,36,NULL,0,1540),
