(N'bc1dc720-86af-522f-8711-4e314e267a49',N'0b40612f-b2b1-557b-b660-026852f7cc95',0,3,19,N'<p>Porters, Cleaners, Dishwasher</p>',N'<p>- Đáp án là B. - Dãy phòng dài phía bắc, phòng ở đầu phía đông được ký hiệu là B trên sơ đồ. - Key word: + northern side (noun phrase): phía bắc + eastern end (noun phrase): đầu phía đông</p>',NULL,NULL,NULL,0,0,18,NULL,0,1472),
