(N'ab1fd5b9-cae2-5ce6-8e09-bc662262011a',N'be64b633-674b-5b56-afbe-1515ed5b00e8',0,3,19,N'<h3>PLAN FOR STUDY SYNDICATE</h3><table border="1"><tbody><tr><td><p><span>Date</span></p></td><td><p><span>Geology Topic</span></p></td><td><p><span>Name of Presenter</span></p></td></tr><tr><td><p>9th May</p></td><td> }{SPACE}{ </td><td><p>Bob</p></td></tr><tr><td> }{SPACE}{ </td><td><p>glaciated areas</p></td><td><p>Andy</p></td></tr><tr><td><p>23rd May</p></td><td><p>rock formation</p></td><td><p>Helen and John</p></td></tr><tr><td> }{SPACE}{ </td><td><p>Volcanoes</p></td><td><p>John</p></td></tr></tbody></table>',N'<p>- Đáp án là mountain building. - Chủ đề địa chất đầu tiên được nêu rõ là “mountain building”. - Khớp với hàng ngày 9th May trong bảng. - Key word: + mountain (noun): núi + building (noun): sự hình thành</p>',NULL,NULL,NULL,0,0,23,NULL,0,1472),
(N'39afc075-9c3e-5833-8e7e-d7cea909bccb',N'be64b633-674b-5b56-afbe-1515ed5b00e8',0,3,19,N'Question number 24',N'<p> Đáp án là 17th May. - Andy loại ngày 16th và chốt ngày 17th cho buổi tiếp theo. - Đây là ngày của chủ đề “glaciated areas”. - Key word: + following week (noun phrase): tuần sau + what about (phrase): đề xuất</p>',NULL,NULL,NULL,0,0,24,NULL,0,1472),
(N'2d165e63-f8f2-51af-91b6-95d176d2bd5c',N'be64b633-674b-5b56-afbe-1515ed5b00e8',0,3,19,N'Question number 25',N'<p>- Đáp án là 29th May. - Ngày 30th bị loại vì Bob không tham gia được, nên thống nhất ngày 29th. - Ngày này ứng với chủ đề “Volcanoes”. - Key word: + can’t make it (phrase): không tham gia được + have to be (phrase): buộc phải</p>',NULL,NULL,NULL,0,0,25,NULL,0,1472),
