(N'25808349-0441-516e-a97f-df59be74b8ab',N'b7c71170-8c5a-5916-93d2-7715c76ec437',0,3,19,N'Question number 2',N'<p>- Đáp án là holidays. </p><p>- Hợp đồng 36 tuần không bao gồm kỳ nghỉ, sinh viên phải dọn phòng. </p><p>- Key word: </p><p>+ include (v) bao gồm </p><p>+ vacate (v) rời khỏi</p>',NULL,NULL,NULL,0,0,2,NULL,0,1445),
