(N'd73acc62-54d5-55a8-8ce7-0d0a57db0a2a',N'7cc44ef7-90fa-5f73-b0a2-0beba24ad18d',0,3,19,N'Question number 23',N'<p>- Đáp án là Object Matters. </p><p>- Đây là tên chính thức của Module 1. </p><p>- Key word: </p><p>+ module (n) học phần </p><p>+ title (n) tiêu đề</p>',NULL,NULL,NULL,0,0,23,NULL,0,1445),
