(N'6e3ea6f0-e59a-5f4d-b423-31a4a562a281',N'ceefee48-d94f-5627-b943-ed49af388b03',0,3,19,N'<h3>Temporary Patient Record Form</h3><table border="1"><tbody><tr><td><p>Street address:</p></td><td> }{SPACE}{ </td></tr><tr><td><p>Suburb:</p></td><td> }{SPACE}{ </td></tr><tr><td><p>Phone number:</p></td><td> }{SPACE}{ </td></tr><tr><td><p><span>Details of injury</span></p></td><td></td></tr><tr><td><p>Sport:</p></td><td><p>Tennis</p></td></tr><tr><td><p>Type of injury:</p></td><td><p>Sprained }{SPACE}{ </p></td></tr><tr><td><p>Date of injury:</p></td><td> }{SPACE}{ </td></tr><tr><td><p><span>Previous treatment and current problems</span></p></td><td></td></tr><tr><td></td><td><p>The patient’s own doctor advised treatment</p></td></tr><tr><td></td><td><p>with }{SPACE}{ The patient is unable</p></td></tr><tr><td></td><td><p>to }{SPACE}{ and. he is experiencing pain</p></td></tr><tr><td></td><td><p>in his }{SPACE}{ at night, which is affecting his sleep. </p></td></tr><tr><td><p><span>Advice given</span></p></td><td></td></tr><tr><td></td><td><p>Stop using the }{SPACE}{ </p></td></tr><tr><td></td><td><p>Do regular }{SPACE}{ at home</p></td></tr></tbody></table>',N'<p>- Đáp án là 95 Cross Street. 
