(N'2ec48013-59f7-5e4f-88dc-a4419202f22a',N'cdf4a33b-c0a0-5933-972c-314c5b5c1580',0,3,19,N'<p>A book about the life and work of Thomas Edison suggests that</p>',N'<p>+ Synonyms:"requires a great deal of hard work" = "resulted from laborious experimentation" (làm việc/thí nghiệm, chăm chỉ)<br>+ Interpretation: "Một cuốn sách về cuộc đời và công việc của Thomas Edison gợi ý rằng<br>+ Answer: những phát minh của Edison có được là từ thí nghiệm liên tục chứ không phải ngẫu nhiên -&gt; chọn đáp án E</p>',NULL,NULL,NULL,0,0,36,NULL,0,1416),
(N'07f8a07a-170a-59dc-a989-4d769f0629eb',N'cdf4a33b-c0a0-5933-972c-314c5b5c1580',0,3,19,N'<p>People who have worked for CEOs like Steve Jobs claim that</p>',N'<p>+ Synonyms: "certain personality types" = "this type of demanding behaviour"; "can limit innovation" = "may squash creativity and innovation"</p><p>+ Interpretation: "Những người đã làm việc cho các CEO như Steve Jobs tuyên bố rằng"</p><p>+ Answer: cách làm việc của Steve Jobs có hại cho nhóm nhân viên -&gt; chọn đáp án G</p>',NULL,NULL,NULL,0,0,37,NULL,0,1416),
