(N'4dcbfcdb-8b74-5367-8fe5-989c9a66b33d',N'9290e829-1255-5340-aed6-9587ffb1c9c9',0,3,19,N'Question number 7',N'<p>Nghe các cụm như “at no charge” = miễn phí, hoặc “fix / repair” = sửa chữa để nhận diện ý chính. </p>',NULL,NULL,NULL,0,0,7,NULL,0,1026),
