(N'57d773b6-df10-597c-b131-e3b34244317f',N'bb8f147f-b095-59c4-8808-0a7b69b4687c',0,3,19,N'Question number 2',N'<p>- Đáp án là 02079460385</p><p>. - Số điện thoại được đọc rõ từng cụm.</p><p> - Khi ghi đáp án IELTS, bỏ khoảng trắng.</p><p> - Key words: </p><p>+ telephone number </p>',NULL,NULL,NULL,0,0,2,NULL,0,1016),
(N'42aa03af-abbd-5562-96eb-32eafb632cda',N'bb8f147f-b095-59c4-8808-0a7b69b4687c',0,3,19,N'Question number 3',N'<p>- Đáp án là August.
