(N'7d4d68f3-cf2a-558c-91d4-60456b0e2e14',N'cca4b77e-912a-5658-8cc7-8ca39103edd8',0,3,19,N'<p>The tutor says that when arranging tutorials with him, Katrina should</p>',N'<p>- Đáp án là A.
