(N'c979b397-e5f2-530f-90bf-ba6abd277da3',N'62aa9d48-710d-51cc-9151-dffaf3daeed4',0,3,19,N'Question number 7',N'<p>- Đáp án là clothing. </p><p>- Lều chính bán quần áo second-hand. </p><p>- Người nói còn nhấn mạnh không bán giày.</p><p> - Key words: </p><p>+ second-hand</p><p>+ clothing </p>',NULL,NULL,NULL,0,0,7,NULL,0,1015),
