CREATE INDEX IX_IAT_L_Topic ON #IAT_L(topic_k,question_k);
IF @@TRANCOUNT<>0 BEGIN
 RAISERROR(N'Run this import in a query window without an existing transaction.',16,1);
 RETURN;
END;
DECLARE @OwnerId bigint, @OwnerName nvarchar(100), @Now datetime2, @LockResult int;
DECLARE @NewQuestions int, @NewAnswers int, @NewTopics int, @NewAnswerLinks int, @NewVocabularyLinks int, @Depth int;
DECLARE @CommitChanges bit;
-- Set 0 to verify and roll back. Set 1 to import.
SET @CommitChanges=1;
SET @OwnerName=N'english'; SET @OwnerId=26; SET @Now=SYSDATETIME();
SET @NewQuestions=0; SET @NewAnswers=0; SET @NewTopics=0; SET @NewAnswerLinks=0; SET @NewVocabularyLinks=0;
BEGIN TRY
 IF (SELECT COUNT(*) FROM #IAT_Q)<>27416 RAISERROR(N'Incomplete staging table Q. No application data imported.',16,1);
IF (SELECT COUNT(*) FROM #IAT_A)<>21916 RAISERROR(N'Incomplete staging table A. No application data imported.',16,1);
IF (SELECT COUNT(*) FROM #IAT_T)<>548 RAISERROR(N'Incomplete staging table T. No application data imported.',16,1);
IF (SELECT COUNT(*) FROM #IAT_L)<>113862 RAISERROR(N'Incomplete staging table L. No application data imported.',16,1);
 IF EXISTS(SELECT name COLLATE Latin1_General_BIN2 FROM #IAT_T GROUP BY name COLLATE Latin1_General_BIN2 HAVING COUNT(*)>1) RAISERROR(N'Duplicate staged topic names; no application data imported.',16,1);
 IF NOT EXISTS(SELECT 1 FROM dbo.tbl_user WHERE id=@OwnerId AND username=@OwnerName) RAISERROR(N'Owner english (26) does not match this database.',16,1);
 IF COL_LENGTH(N'dbo.tbl_question',N'level') IS NULL OR COL_LENGTH(N'dbo.tbl_topic',N'content_html') IS NULL RAISERROR(N'IELTSRoom schema does not match the verified schema.',16,1);
 IF (SELECT COUNT(*) FROM dbo.tbl_question_type WHERE id IN(6,11,13,14,15,18,19))<>7 RAISERROR(N'Required IELTSRoom question types are missing.',16,1);
 BEGIN TRANSACTION;
 EXEC @LockResult=sys.sp_getapplock @Resource=N'IELTSRoom-IAT-import-english-20261106',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=30000;
 IF @LockResult<0 RAISERROR(N'Another import is in progress. Retry later.',16,1);
 IF EXISTS(SELECT 1 FROM dbo.tbl_question q JOIN #IAT_Q s ON q.uuid_key=s.k WHERE s.user_owned=1 AND ISNULL(q.user_id,-1)<>@OwnerId) RAISERROR(N'Import UUID belongs to another owner.',16,1);
 IF EXISTS(SELECT 1 FROM dbo.tbl_topic t JOIN #IAT_T s ON t.uuid_key=s.k WHERE ISNULL(t.user_id,-1)<>@OwnerId) RAISERROR(N'Topic UUID belongs to another owner.',16,1);

 SELECT s.k,MIN(q.id) FROM #IAT_Q s JOIN dbo.tbl_question q
 ON q.user_id=@OwnerId AND q.question_type=6 AND q.parent_id IS NULL
 AND q.question COLLATE Latin1_General_BIN2=s.question COLLATE Latin1_General_BIN2
 AND ISNULL(q.mother_tongue,N'') COLLATE Latin1_General_BIN2=ISNULL(s.mother_tongue,N'') COLLATE Latin1_General_BIN2
 AND ISNULL(q.pronounce,N'') COLLATE Latin1_General_BIN2=ISNULL(s.pronounce,N'') COLLATE Latin1_General_BIN2
 AND ISNULL(q.level,N'')=ISNULL(s.level,N'')
 WHERE s.kind=1 AND NOT EXISTS(SELECT 1 FROM #IAT_QM m WHERE m.k=s.k) GROUP BY s.k;

 -- Prefer the stable import UUID; use a matching legacy name only when unmapped.
 ON t.user_id=@OwnerId AND t.uuid_key=s.k GROUP BY s.k;
 ON t.user_id=@OwnerId AND t.name COLLATE Latin1_General_BIN2=s.name COLLATE Latin1_General_BIN2
 WHERE NOT EXISTS(SELECT 1 FROM #IAT_TM m WHERE m.k=s.k) GROUP BY s.k;
 OUTPUT inserted.uuid_key,inserted.id INTO #IAT_TM(k,id)
 SELECT @Now,@OwnerName,s.k,0,s.name,@OwnerId,s.content_html,1 FROM #IAT_T s WHERE NOT EXISTS(SELECT 1 FROM #IAT_TM m WHERE m.k=s.k);
 SET @NewTopics=@@ROWCOUNT;
 -- Preserve existing topic content and append required dictionary attribution if missing.
 UPDATE t SET content_html=ISNULL(t.content_html,N'')+s.content_html,modify_date=@Now,modified_by=@OwnerName
 FROM dbo.tbl_topic t JOIN #IAT_TM m ON m.id=t.id JOIN #IAT_T s ON s.k=m.k
 WHERE ISNULL(t.content_html,N'') NOT LIKE N'%thichhoc-dict%';

 SET @Depth=0;
 WHILE @Depth<=3 BEGIN
  OUTPUT inserted.uuid_key,inserted.id INTO #IAT_QM(k,id)
  SELECT @Now,@OwnerName,s.k,0,s.question,s.description,s.mother_tongue,s.pronounce,s.title,s.type,s.status,s.ordinal_number,s.level,
   CASE WHEN s.user_owned=1 THEN @OwnerId ELSE NULL END,s.question_type,p.id,0,0,0,0
  FROM #IAT_Q s LEFT JOIN #IAT_QM p ON p.k=s.parent_k
  WHERE s.depth=@Depth AND NOT EXISTS(SELECT 1 FROM #IAT_QM m WHERE m.k=s.k) AND (s.parent_k IS NULL OR p.id IS NOT NULL);
  SET @NewQuestions=@NewQuestions+@@ROWCOUNT;
  SET @Depth=@Depth+1;
 END;
 IF (SELECT COUNT(*) FROM #IAT_QM)<>(SELECT COUNT(*) FROM #IAT_Q) RAISERROR(N'Question parent mapping incomplete; rolled back.',16,1);

 OUTPUT inserted.uuid_key,inserted.id INTO #IAT_AM(k,id)
 SELECT @Now,@OwnerName,s.k,0,s.answer FROM #IAT_A s WHERE NOT EXISTS(SELECT 1 FROM #IAT_AM m WHERE m.k=s.k);
 SET @NewAnswers=@@ROWCOUNT;
 SELECT @Now,@OwnerName,s.qa_k,0,q.id,a.id,s.is_correct,s.ordinal_number FROM #IAT_A s JOIN #IAT_QM q ON q.k=s.question_k JOIN #IAT_AM a ON a.k=s.k
 WHERE NOT EXISTS(SELECT 1 FROM dbo.tbl_question_answer x WHERE x.uuid_key=s.qa_k OR (x.question=q.id AND x.answer=a.id));
 SET @NewAnswerLinks=@@ROWCOUNT;
 SELECT @Now,@OwnerName,s.k,0,q.id,t.id FROM #IAT_L s JOIN #IAT_QM q ON q.k=s.question_k JOIN #IAT_TM t ON t.k=s.topic_k
 WHERE NOT EXISTS(SELECT 1 FROM dbo.tbl_question_topic x WHERE x.question=q.id AND x.topic=t.id);
 SET @NewVocabularyLinks=@@ROWCOUNT;
 IF EXISTS(SELECT 1 FROM #IAT_T s JOIN #IAT_TM t ON t.k=s.k WHERE
  (SELECT COUNT(DISTINCT q.id) FROM #IAT_L l JOIN #IAT_QM q ON q.k=l.question_k WHERE l.topic_k=s.k)<s.expected_words)
  RAISERROR(N'Vocabulary topic count check failed; rolled back.',16,1);
 IF @CommitChanges=1 COMMIT TRANSACTION; ELSE ROLLBACK TRANSACTION;
 SELECT @CommitChanges AS Committed,@NewQuestions AS NewQuestionNodes,@NewAnswers AS NewAnswerOptions,@NewTopics AS NewTopics,@NewAnswerLinks AS NewAnswerLinks,@NewVocabularyLinks AS NewVocabularyLinks;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
 DECLARE @Error nvarchar(2048); SET @Error=ERROR_MESSAGE(); RAISERROR(N'%s',16,1,@Error);
END CATCH;
